[{"order":1,"type":"heading","text":"Unit Testing ViewModels and State Logic in SwiftUI"},{"order":2,"type":"paragraph","text":"Writing robust unit tests for your SwiftUI ViewModels is essential for maintaining predictable state logic, preventing regressions, and ensuring your business rules hold up over time. Because SwiftUI relies heavily on the ObservableObject protocol or the newer Observation framework, testing state mutations becomes straightforward if you structure your architecture correctly."},{"order":3,"type":"subheading","text":"Setting Up the ViewModel"},{"order":4,"type":"paragraph","text":"Let us consider a practical example: a TodoViewModel that handles fetching tasks, adding new tasks, and toggling completion states. We want to test these state transitions reliably without hitting a real network or persistence layer."},{"order":5,"type":"code","text":"import Foundation

struct Todo: Identifiable, Equatable {
    let id: UUID
    var title: String
    var isCompleted: Bool
}

protocol TodoServiceProtocol {
    func fetchTodos() async throws -> [Todo]
}

@MainActor
class TodoViewModel: ObservableObject {
    @Published var todos: [Todo] = []
    @Published var isLoading: Bool = false
    @Published var errorMessage: String? = nil

    private let service: TodoServiceProtocol

    init(service: TodoServiceProtocol) {
        self.service = service
    }

    func loadTodos() async {
        isLoading = true
        errorMessage = nil
        do {
            todos = try await service.fetchTodos()
        } catch {
            errorMessage = error.localizedDescription
        }
        isLoading = false
    }

    func toggleCompletion(for todo: Todo) {
        if let index = todos.firstIndex(where: { $0.id == todo.id }) {
            todos[index].isCompleted.toggle()
        }
    }
}"},{"order":6,"type":"subheading","text":"Creating a Mock Service"},{"order":7,"type":"paragraph","text":"To test the ViewModel in isolation, we implement a mock service conforming to TodoServiceProtocol. This allows us to simulate both successful responses and error states deterministically."},{"order":8,"type":"code","text":"class MockTodoService: TodoServiceProtocol {
    var shouldThrowError = false
    var mockTodos: [Todo] = [
        Todo(id: UUID(), title: "Write tests", isCompleted: false),
        Todo(id: UUID(), title: "Refactor code", isCompleted: true)
    ]

    func fetchTodos() async throws -> [Todo] {
        if shouldThrowError {
            throw NSError(domain: "TestError", code: -1, userInfo: [NSLocalizedDescriptionKey: "Failed to fetch"])
        }
        return mockTodos
    }
}"},{"order":9,"type":"subheading","text":"Writing the Unit Tests"},{"order":10,"type":"paragraph","text":"Using XCTest, we can verify that our ViewModel correctly updates its published properties when asynchronous methods complete. Notice the use of await when calling asynchronous ViewModel actions."},{"order":11,"type":"code","text":"import XCTest
@testable import YourAppModule

@MainActor
class TodoViewModelTests: XCTestCase {

    var service: MockTodoService!
    var sut: TodoViewModel!

    override func setUp() {
        super.setUp()
        service = MockTodoService()
        sut = TodoViewModel(service: service)
    }

    override func tearDown() {
        service = nil
        sut = nil
        super.tearDown()
    }

    func testLoadTodosSuccess() async {
        // Given
        XCTAssertFalse(sut.isLoading)
        XCTAssertTrue(sut.todos.isEmpty)

        // When
        await sut.loadTodos()

        // Then
        XCTAssertFalse(sut.isLoading)
        XCTAssertEqual(sut.todos.count, 2)
        XCTAssertNil(sut.errorMessage)
        XCTAssertEqual(sut.todos[0].title, "Write tests")
    }

    func testLoadTodosFailure() async {
        // Given
        service.shouldThrowError = true

        // When
        await sut.loadTodos()

        // Then
        XCTAssertFalse(sut.isLoading)
        XCTAssertTrue(sut.todos.isEmpty)
        XCTAssertEqual(sut.errorMessage, "Failed to fetch")
    }

    func testToggleCompletion() async {
        // Given
        await sut.loadTodos()
        let targetTodo = sut.todos[0]
        XCTAssertFalse(targetTodo.isCompleted)

        // When
        sut.toggleCompletion(for: targetTodo)

        // Then
        XCTAssertTrue(sut.todos[0].isCompleted)
    }
}"},{"order":12,"type":"subheading","text":"Best Practices for Testing SwiftUI Logic"},{"order":13,"type":"bullet_point","text":"Always isolate your dependencies using protocols to enable easy mocking."},{"order":14,"type":"bullet_point","text":"Annotate your ViewModels and test classes with @MainActor when dealing with UI-bound state published properties."},{"order":15,"type":"bullet_point","text":"Test both happy paths and error states to ensure robust error handling in the UI."},{"order":16,"type":"bullet_point","text":"Keep your ViewModels free of SwiftUI View imports (like SwiftUI itself) to maximize testability and separation of concerns."}]
